https://zenn.dev/hsaki/books/golang-grpc-starting/viewer/bistream

双方向ストリームもinterfaceに差分あり。

```go
type GreetingServiceServer interface {
	// サービスが持つメソッドの定義
	Hello(context.Context, *HelloRequest) (*HelloResponse, error)
	// サーバーストリーミングRPC
	HelloServerStream(*HelloRequest, GreetingService_HelloServerStreamServer) error
	// クライアントストリーミングRPC
	HelloClientStream(GreetingService_HelloClientStreamServer) error
	// 双方向ストリーミングRPC
	HelloBiStreams(GreetingService_HelloBiStreamsServer) error
	mustEmbedUnimplementedGreetingServiceServer()
}

type GreetingService_HelloBiStreamsServer interface {
	Send(*HelloResponse) error
	Recv() (*HelloRequest, error)
	grpc.ServerStream
}
```

```go
type GreetingServiceServer interface {
	// Unary RPC
	Hello(context.Context, *HelloRequest) (*HelloResponse, error)
	// Server streaming RPC
	HelloServerStream(*HelloRequest, grpc.ServerStreamingServer[HelloResponse]) error
	// Client streaming RPC
	HelloClientStream(grpc.ClientStreamingServer[HelloRequest, HelloResponse]) error
	// Bidirectional streaming RPC
	HelloBiStreams(grpc.BidiStreamingServer[HelloRequest, HelloResponse]) error
	mustEmbedUnimplementedGreetingServiceServer()
}

// /Users/okuma/go/pkg/mod/google.golang.org/grpc@v1.70.0/stream_interfaces.go
type BidiStreamingServer[Req any, Res any] interface {
	// Recv receives the next request message from the client.  The server may
	// repeatedly call Recv to read messages from the request stream.  If
	// io.EOF is returned, it indicates the client called CloseSend on its
	// BidiStreamingClient.  Any other error indicates the stream was
	// terminated unexpectedly, and the handler method should return, as the
	// stream is no longer usable.
	Recv() (*Req, error)

	// Send sends a response message to the client.  The server handler may
	// call Send multiple times to send multiple messages to the client.  An
	// error is returned if the stream was terminated unexpectedly, and the
	// handler method should return, as the stream is no longer usable.
	Send(*Res) error

	// ServerStream is embedded to provide Context, SetHeader, SendHeader, and
	// SetTrailer functionality.  No other methods in the ServerStream should
	// be called directly.
	ServerStream
}
```

